RedBlackTree.algorithm:
class RBNode:
    def __init__(self, key, color='RED'):
        self.key = key
        self.color = color
        self.left = None
        self.right = None
        self.parent = None

function insert(root, key):
    // 1. Стандартная вставка в BST
    node = BSTInsert(root, key)
    node.color = 'RED'

    // 2. Исправление нарушений свойств красно-черного дерева
    while node != root and node.parent.color == 'RED':
        if node.parent == node.parent.parent.left:
            uncle = node.parent.parent.right

            if uncle.color == 'RED':
                // Случай 1: дядя красный
                node.parent.color = 'BLACK'
                uncle.color = 'BLACK'
                node.parent.parent.color = 'RED'
                node = node.parent.parent
            else:
                if node == node.parent.right:
                    // Случай 2: узел - правый потомок
                    node = node.parent
                    root = leftRotate(root, node)

                // Случай 3: узел - левый потомок
                node.parent.color = 'BLACK'
                node.parent.parent.color = 'RED'
                root = rightRotate(root, node.parent.parent)
        else:
            // Симметричный случай

    root.color = 'BLACK'
    return root

SplayTree.algorithm:
function splay(root, key):
    if root is None or root.key == key:
        return root

    if key < root.key:
        if root.left is None:
            return root

        // Zig-Zig (лево-лево)
        if key < root.left.key:
            root.left.left = splay(root.left.left, key)
            root = rightRotate(root)
        // Zig-Zag (лево-право)
        elif key > root.left.key:
            root.left.right = splay(root.left.right, key)
            if root.left.right:
                root.left = leftRotate(root.left)

        return rightRotate(root) if root.left else root

    else: // симметричный случай для правого поддерева

Treap.algorithm:
class TreapNode:
    def __init__(self, key):
        self.key = key
        self.priority = random()  // случайный приоритет
        self.left = None
        self.right = None

function insert(root, key):
    if root is None:
        return TreapNode(key)

    if key <= root.key:
        root.left = insert(root.left, key)

        // Восстановление свойства кучи
        if root.left.priority > root.priority:
            root = rightRotate(root)
    else:
        root.right = insert(root.right, key)

        if root.right.priority > root.priority:
            root = leftRotate(root)

    return root

BTree.algorithm:
class BTreeNode:
    def __init__(self, t, leaf=False):
        self.t = t          // минимальная степень
        self.leaf = leaf    // является ли узел листом
        self.keys = []      // список ключей
        self.children = []  // список дочерних узлов

function search(node, key):
    i = 0
    while i < len(node.keys) and key > node.keys[i]:
        i += 1

    if i < len(node.keys) and node.keys[i] == key:
        return (node, i)

    if node.leaf:
        return None

    return search(node.children[i], key)

Heap.algorithm:
class MinHeap:
    def __init__(self):
        self.heap = []

    def parent(self, i):
        return (i-1)//2

    def insert(self, k):
        self.heap.append(k)
        i = len(self.heap) - 1

        // Просеивание вверх
        while i != 0 and self.heap[self.parent(i)] > self.heap[i]:
            self.heap[i], self.heap[self.parent(i)] = \
                self.heap[self.parent(i)], self.heap[i]
            i = self.parent(i)

    def heapify(self, i):
        // Просеивание вниз
        smallest = i
        left = 2*i + 1
        right = 2*i + 2

        if left < len(self.heap) and self.heap[left] < self.heap[smallest]:
            smallest = left
        if right < len(self.heap) and self.heap[right] < self.heap[smallest]:
            smallest = right

        if smallest != i:
            self.heap[i], self.heap[smallest] = self.heap[smallest], self.heap[i]
            self.heapify(smallest)
